 'use client';
import {paceExportRows} from '@/lib/revenue-pace-export';
import {downloadReport} from '@/lib/report-export';
import {useState,useRef,useEffect} from 'react';
import {flushSync} from 'react-dom';
import {PickupEvidence} from '@/components/pickup-evidence';
import {bookingPaceReport} from '@/lib/revenue-pace-report';
import {pickupMoney} from '@/lib/pickup-money';
import type {RevenueSnapshot} from '@/lib/revenue-pickup';
import type {RoomType} from '@/lib/pilot';
type Props={tenant:string;property:string;referenceCapture:string;currentCapture:string;reference:unknown;current:unknown;old:RevenueSnapshot[];later:RevenueSnapshot[];timeZone:string;types:RoomType[]};
export function BookingPace(p:Props){
 return <BookingPaceSession key={JSON.stringify([p.tenant,p.property,p.referenceCapture,p.currentCapture,p.timeZone])} {...p}/>;
}
function BookingPaceSession(p:Props){
 const [referenceDate,setReferenceDate]=useState(''),[currentDate,setCurrentDate]=useState(''),[rows,setRows]=useState<ReturnType<typeof bookingPaceReport>|null>(null),[error,setError]=useState('');
 const [page,setPage]=useState(0),[printing,setPrinting]=useState(false);
 useEffect(()=>{const begin=()=>flushSync(()=>setPrinting(true)),end=()=>setPrinting(false);window.addEventListener('beforeprint',begin);window.addEventListener('afterprint',end);return()=>{window.removeEventListener('beforeprint',begin);window.removeEventListener('afterprint',end)}},[]);
 const [evidence,setEvidence]=useState<{capture:string;snapshot:RevenueSnapshot;label:string}|null>(null);
 const panel=useRef<HTMLDivElement>(null),trigger=useRef<HTMLButtonElement|null>(null);
 useEffect(()=>{if(evidence){panel.current?.focus();panel.current?.scrollIntoView?.({block:'nearest'});}},[evidence]);
 function compare(){setPage(0);setEvidence(null);setRows(null);setError('');try{setRows(bookingPaceReport({...p,pairs:[{reference:referenceDate,current:currentDate}]}))}catch(e){setError(e instanceof Error?e.message:'Pace comparison unavailable.');}}
 return <section aria-label="Booking pace"><h3>Booking pace · preview</h3><p>Compare two different stay nights at the same number of days before arrival and the same local capture time. Property time zone: {p.timeZone}. Choose comparable dates; this is not a forecast.</p><div className="form-grid"><label className="field">Reference stay night<select value={referenceDate} onChange={e=>{setReferenceDate(e.target.value);setRows(null);setEvidence(null);setError('')}}><option value="">Select a night</option>{[...new Set(p.old.map(s=>s.stayDate))].sort().map(day=><option key={day}>{day}</option>)}</select></label><label className="field">Current stay night<select value={currentDate} onChange={e=>{setCurrentDate(e.target.value);setRows(null);setEvidence(null);setError('')}}><option value="">Select a night</option>{[...new Set(p.later.map(s=>s.stayDate))].sort().map(day=><option key={day}>{day}</option>)}</select></label></div><button className="secondary" disabled={!referenceDate||!currentDate} onClick={compare}>Compare booking pace</button>{error&&<p role="alert">{error}</p>}{rows&&<button className="secondary" onClick={()=>{try{downloadReport('booking-pace-'+p.property,paceExportRows({...p,pairs:[{reference:referenceDate,current:currentDate}]},p.types))}catch(e){setError(e instanceof Error?e.message:'Download failed.')}}}>Download pace CSV</button>}{rows&&<div className="pilot-table-wrap"><table className="pilot-table"><caption>Booking pace: {referenceDate} compared with {currentDate}</caption><thead><tr><th scope="col">Room type</th><th scope="col">Days before arrival</th><th scope="col">Booked-night difference</th><th scope="col">Room revenue difference</th><th scope="col">Capacity difference</th><th scope="col">Reference occupancy</th><th scope="col">Current occupancy</th><th scope="col">Occupancy change (percentage points)</th><th scope="col">Saved reservations</th></tr></thead><tbody>{(printing?rows:rows.slice(page*50,(page+1)*50)).map(row=>{const r=row.comparison,currency=p.later.find(s=>s.roomTypeId===row.roomTypeId)?.currency??p.old.find(s=>s.roomTypeId===row.roomTypeId)?.currency??'USD';return <tr key={row.roomTypeId}><th scope="row">{p.types.find(t=>t.id===row.roomTypeId)?.name??'Unknown room type'}</th>{r.available?<><td>{r.leadDays}</td><td>{r.roomNightsDifference}</td><td>{pickupMoney(r.revenueDifferenceMinor,currency)}</td><td>{r.capacityDifference??'Unavailable'}</td><td>{r.previousOccupancy===null?'Unavailable':(r.previousOccupancy*100).toFixed(1)+'%'}</td><td>{r.currentOccupancy===null?'Unavailable':(r.currentOccupancy*100).toFixed(1)+'%'}</td><td>{r.occupancyPercentagePointDifference===null?'Unavailable':r.occupancyPercentagePointDifference.toFixed(1)}</td></>:<td colSpan={7}>{r.reason}</td>}<td>{([{capture:p.referenceCapture,snapshot:p.old.find(s=>s.roomTypeId===row.roomTypeId&&s.stayDate===row.referenceDate),label:'Reference'},{capture:p.currentCapture,snapshot:p.later.find(s=>s.roomTypeId===row.roomTypeId&&s.stayDate===row.currentDate),label:'Current'}]).map(({capture,snapshot,label})=>snapshot&&<button className="text-button" key={label} onClick={e=>{trigger.current=e.currentTarget;setEvidence({capture,snapshot,label})}}>{label} reservations</button>)}</td></tr>})}</tbody></table>{!printing&&rows.length>50&&<nav aria-label="Booking pace pages"><button className="secondary" disabled={page===0} onClick={()=>{setPage(n=>n-1);setEvidence(null)}}>Previous pace rows</button><span role="status">Pace rows {page*50+1}–{Math.min((page+1)*50,rows.length)} of {rows.length}</span><button className="secondary" disabled={(page+1)*50>=rows.length} onClick={()=>{setPage(n=>n+1);setEvidence(null)}}>Next pace rows</button></nav>}</div>}{rows&&evidence&&<div ref={panel} tabIndex={-1} role="region" aria-label="Pace reservation details"><button className="secondary" onClick={()=>{setEvidence(null);trigger.current?.focus()}}>Close pace details</button><PickupEvidence key={[evidence.capture,evidence.snapshot.roomTypeId,evidence.snapshot.stayDate].join(':')} tenant={p.tenant} property={p.property} capture={evidence.capture} roomType={evidence.snapshot.roomTypeId} day={evidence.snapshot.stayDate} currency={evidence.snapshot.currency} label={evidence.label+' capture'} roomTypeName={p.types.find(t=>t.id===evidence.snapshot.roomTypeId)?.name} capturedAt={evidence.snapshot.capturedAt}/></div>}</section>;
}
